// FILE: src/main/java/com/example/preview/MetadataFetcher.java
package com.example.preview;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Performs an external HTTP GET against a target URL, parses the {@code <title>}
 * and {@code <meta name="description">} from the HTML head, and returns them as
 * a {@link FetchResult}.
 *
 * <p>Reads only until {@code </head>} to minimise bandwidth, and honours the
 * fetch timeout and max-redirect settings from {@link PreviewConfig}.
 */
public class MetadataFetcher {

    private static final Pattern TITLE_PATTERN =
            Pattern.compile("<title[^>]*>([^<]*)</title>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);

    private static final Pattern DESCRIPTION_PATTERN =
            Pattern.compile(
                    "<meta[^>]+name=[\"']description[\"'][^>]+content=[\"']([^\"']*)[\"']" +
                    "|<meta[^>]+content=[\"']([^\"']*)[\"'][^>]+name=[\"']description[\"']",
                    Pattern.CASE_INSENSITIVE | Pattern.DOTALL);

    private static final Pattern END_OF_HEAD =
            Pattern.compile("</head>", Pattern.CASE_INSENSITIVE);

    private static final int READ_BUFFER_SIZE = 8192;
    /** Maximum characters we read from the response before giving up. */
    private static final int MAX_CHARS = 256 * 1024; // 256 KB

    private final PreviewConfig config;

    public MetadataFetcher(PreviewConfig config) {
        this.config = config;
    }

    /**
     * Fetch the target URL and extract preview metadata.
     *
     * @param targetUrl the fully-qualified URL to fetch
     * @return a {@link FetchResult} containing extracted title and description
     * @throws IOException if the fetch fails for any reason (including timeout)
     */
    public FetchResult fetch(String targetUrl) throws IOException {
        String html = downloadHead(targetUrl, config.getMaxRedirects());
        String title       = extractTitle(html);
        String description = extractDescription(html);
        return new FetchResult(title, description);
    }

    // -------------------------------------------------------------------------
    // Internals
    // -------------------------------------------------------------------------

    private String downloadHead(String urlString, int redirectsLeft) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        try {
            conn.setInstanceFollowRedirects(false);
            conn.setRequestMethod("GET");
            conn.setConnectTimeout((int) config.getFetchTimeoutMs());
            conn.setReadTimeout((int) config.getFetchTimeoutMs());
            conn.setRequestProperty("Accept", "text/html,application/xhtml+xml;q=0.9,*/*;q=0.8");
            conn.setRequestProperty("User-Agent", "UrlShortener-Preview/1.0");

            int status = conn.getResponseCode();

            if (status >= 300 && status < 400) {
                if (redirectsLeft <= 0) {
                    throw new IOException("Too many redirects fetching " + urlString);
                }
                String location = conn.getHeaderField("Location");
                if (location == null || location.isBlank()) {
                    throw new IOException("Redirect with no Location header from " + urlString);
                }
                // Resolve relative redirects
                if (!location.startsWith("http://") && !location.startsWith("https://")) {
                    URL base = new URL(urlString);
                    location = new URL(base, location).toExternalForm();
                }
                return downloadHead(location, redirectsLeft - 1);
            }

            if (status < 200 || status >= 300) {
                throw new IOException("Unexpected HTTP status " + status + " from " + urlString);
            }

            try (InputStream is = conn.getInputStream()) {
                return readUntilEndOfHead(is);
            }
        } finally {
            conn.disconnect();
        }
    }

    private String readUntilEndOfHead(InputStream is) throws IOException {
        StringBuilder sb = new StringBuilder();
        BufferedReader reader = new BufferedReader(
                new InputStreamReader(is, StandardCharsets.UTF_8), READ_BUFFER_SIZE);
        char[] buf = new char[READ_BUFFER_SIZE];
        int read;
        while ((read = reader.read(buf)) != -1) {
            sb.append(buf, 0, read);
            if (sb.length() > MAX_CHARS) {
                break;
            }
            if (END_OF_HEAD.matcher(sb).find()) {
                break;
            }
        }
        return sb.toString();
    }

    private String extractTitle(String html) {
        Matcher m = TITLE_PATTERN.matcher(html);
        if (m.find()) {
            return m.group(1).trim();
        }
        return null;
    }

    private String extractDescription(String html) {
        Matcher m = DESCRIPTION_PATTERN.matcher(html);
        if (m.find()) {
            String g1 = m.group(1);
            String g2 = m.group(2);
            String val = (g1 != null) ? g1 : g2;
            return (val != null) ? val.trim() : null;
        }
        return null;
    }

    // -------------------------------------------------------------------------
    // Result type
    // -------------------------------------------------------------------------

    public static final class FetchResult {
        private final String title;
        private final String description;

        public FetchResult(String title, String description) {
            this.title       = title;
            this.description = description;
        }

        public String getTitle()       { return title; }
        public String getDescription() { return description; }
    }
}


