package com.example.preview;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Read/write abstraction over a preview cache.
 *
 * This implementation uses an in-process ConcurrentHashMap as a fallback store
 * (used when no Redis dependency is available on the classpath). It respects
 * the TTL defined in PreviewConfig by checking expiry times on every read.
 */
public class PreviewCache {

    private static final String KEY_PREFIX = "preview:";

    private final PreviewConfig config;
    private final ObjectMapper objectMapper;

    // In-process fallback store: key → (expiresAt epoch second, serialized JSON)
    private final Map<String, CacheEntry> store = new ConcurrentHashMap<>();

    public PreviewCache(PreviewConfig config) {
        this.config = config;
        this.objectMapper = new ObjectMapper()
                .registerModule(new JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    }

    /**
     * Retrieve a cached PreviewDocument for the given short code.
     * Returns empty if the key is absent or has expired.
     */
    public Optional<PreviewDocument> get(String shortCode) {
        String key = KEY_PREFIX + shortCode;
        CacheEntry entry = store.get(key);
        if (entry == null) {
            return Optional.empty();
        }
        if (Instant.now().isAfter(entry.expiresAt)) {
            store.remove(key);
            return Optional.empty();
        }
        try {
            PreviewDocument doc = objectMapper.readValue(entry.json, PreviewDocument.class);
            return Optional.of(doc);
        } catch (JsonProcessingException e) {
            store.remove(key);
            return Optional.empty();
        }
    }

    /**
     * Store a PreviewDocument in the cache, using the configured TTL.
     * Uses atomic putIfAbsent semantics to reduce stampede risk on first write.
     */
    public void put(String shortCode, PreviewDocument document) {
        String key = KEY_PREFIX + shortCode;
        try {
            String json = objectMapper.writeValueAsString(document);
            long ttlSeconds = config.getCacheTtlSeconds();
            Instant expiresAt = Instant.now().plusSeconds(ttlSeconds);
            CacheEntry entry = new CacheEntry(json, expiresAt);
            // Atomic put-if-absent to avoid stampede overwrite
            store.putIfAbsent(key, entry);
        } catch (JsonProcessingException e) {
            // If serialization fails, we simply don't cache — not a fatal error
        }
    }

    /**
     * Forcefully write (overwrite) an entry, regardless of whether one already exists.
     */
    public void set(String shortCode, PreviewDocument document) {
        String key = KEY_PREFIX + shortCode;
        try {
            String json = objectMapper.writeValueAsString(document);
            long ttlSeconds = config.getCacheTtlSeconds();
            Instant expiresAt = Instant.now().plusSeconds(ttlSeconds);
            store.put(key, new CacheEntry(json, expiresAt));
        } catch (JsonProcessingException e) {
            // Swallow — caching is best-effort
        }
    }

    /**
     * Remove a cached entry for the given short code.
     */
    public void evict(String shortCode) {
        store.remove(KEY_PREFIX + shortCode);
    }

    // -------------------------------------------------------------------------
    // Internal value type
    // -------------------------------------------------------------------------

    private static final class CacheEntry {
        final String json;
        final Instant expiresAt;

        CacheEntry(String json, Instant expiresAt) {
            this.json = json;
            this.expiresAt = expiresAt;
        }
    }
}


