package com.example.preview;

/**
 * Configuration value object for the preview subsystem.
 * All timeout and TTL values are externalised here so they can be tuned
 * without a code change (e.g. loaded from application.properties).
 */
public class PreviewConfig {

    /** Maximum milliseconds to wait for the external HTML fetch. */
    private final long fetchTimeoutMs;

    /** Maximum milliseconds for the overall preview SLA (cache + fetch). */
    private final long cacheTimeoutMs;

    /** How long (seconds) a cached PreviewDocument should live in the store. */
    private final long cacheTtlSeconds;

    /** Maximum number of HTTP redirects MetadataFetcher will follow. */
    private final int maxRedirects;

    public PreviewConfig() {
        this(3_000L, 3_000L, 86_400L, 5);
    }

    public PreviewConfig(long fetchTimeoutMs, long cacheTimeoutMs,
                         long cacheTtlSeconds, int maxRedirects) {
        this.fetchTimeoutMs  = fetchTimeoutMs;
        this.cacheTimeoutMs  = cacheTimeoutMs;
        this.cacheTtlSeconds = cacheTtlSeconds;
        this.maxRedirects    = maxRedirects;
    }

    public long getFetchTimeoutMs()  { return fetchTimeoutMs; }
    public long getCacheTimeoutMs()  { return cacheTimeoutMs; }
    public long getCacheTtlSeconds() { return cacheTtlSeconds; }
    public int  getMaxRedirects()    { return maxRedirects; }
}


