package com.example.preview;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;

import java.time.Instant;

/**
 * Value object holding the preview metadata for a short URL.
 */
public class PreviewDocument {

    private final String shortCode;
    private final String targetUrl;
    private final String title;          // nullable
    private final String description;   // nullable
    private final Instant fetchedAt;
    private final Instant cacheExpiresAt;

    @JsonCreator
    public PreviewDocument(
            @JsonProperty("shortCode")      String shortCode,
            @JsonProperty("targetUrl")      String targetUrl,
            @JsonProperty("title")          String title,
            @JsonProperty("description")    String description,
            @JsonProperty("fetchedAt")      Instant fetchedAt,
            @JsonProperty("cacheExpiresAt") Instant cacheExpiresAt) {
        this.shortCode      = shortCode;
        this.targetUrl      = targetUrl;
        this.title          = title;
        this.description    = description;
        this.fetchedAt      = fetchedAt;
        this.cacheExpiresAt = cacheExpiresAt;
    }

    public String  getShortCode()      { return shortCode; }
    public String  getTargetUrl()      { return targetUrl; }
    public String  getTitle()          { return title; }
    public String  getDescription()    { return description; }
    public Instant getFetchedAt()      { return fetchedAt; }
    public Instant getCacheExpiresAt() { return cacheExpiresAt; }

    @Override
    public String toString() {
        return "PreviewDocument{shortCode='" + shortCode + "', targetUrl='" + targetUrl + "'}";
    }
}




