    // -------------------------------------------------------------------------

    @Test
    void testAC_1EndToEndPreviewRoundTripForKnownShortCode() {
        // Arrange
        String shortCode = "aB3xQ";
        String targetUrl = "https://example.com/some/article";
        PreviewConfig config = new PreviewConfig();
        PreviewCache  cache  = new PreviewCache(config);

        // Simulate MetadataFetcher result
        MetadataFetcher.FetchResult fetchResult =
                new MetadataFetcher.FetchResult("Example Domain", "An example article about something");

        // Build the document (as PreviewService would)
        Instant fetchedAt    = Instant.now();
        Instant cacheExpires = fetchedAt.plusSeconds(config.getCacheTtlSeconds());
        PreviewDocument document = new PreviewDocument(
                shortCode,
                targetUrl,
                fetchResult.getTitle(),
                fetchResult.getDescription(),
                fetchedAt,
                cacheExpires);

        // Act – store in cache then retrieve
        cache.put(shortCode, document);
        var retrieved = cache.get(shortCode);

        // Assert – all API-contract-required fields are present and correct
        assertTrue(retrieved.isPresent(), "Preview must be available for a known short code");

        PreviewDocument result = retrieved.get();
        assertAll("All preview fields must be returned for a known short code (AC-1)",
                () -> assertEquals(shortCode,        result.getShortCode()),
                () -> assertEquals(targetUrl,         result.getTargetUrl()),
                () -> assertEquals("Example Domain",                           result.getTitle()),
                () -> assertEquals("An example article about something",        result.getDescription()),
                () -> assertNotNull(result.getFetchedAt()),
                () -> assertNotNull(result.getCacheExpiresAt()),
                () -> assertTrue(result.getCacheExpiresAt().isAfter(result.getFetchedAt()),
                        "cacheExpiresAt must be after fetchedAt")
        );
    }
